/* C API of the Rust port of `src/checksum.c`, generated by rust-anything. */
#ifndef CHECKSUM_RS_H
#define CHECKSUM_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint32_t adler32(const char *data);
uint32_t fnv1a(const char *data);
int clamp(int value, int low, int high);
long gcd(long a, long b);
double mean3(double a, double b, double c);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint32_t rust_anything_adler32(const char *data);
uint32_t rust_anything_fnv1a(const char *data);
int rust_anything_clamp(int value, int low, int high);
long rust_anything_gcd(long a, long b);
double rust_anything_mean3(double a, double b, double c);

#endif /* CHECKSUM_RS_H */
